-- Read-only audit queries; company ID 24bc0b21-4e2d-4413-9842-31719a3669f4; cutoffs 2025-12-31 and 2026-08-31.

-- status
select case when entry_date <= date '2025-12-31' then 'through_2025' when entry_date <= date '2026-08-31' then 'jan_aug_2026' else 'after_cutoff' end as period,status,count(*) as entries,min(entry_date) as earliest,max(entry_date) as latest,sum(total_debit) as header_debit,count(*) filter(where reversal_entry_id is not null) as with_reversal_id,count(*) filter(where reversed_at is not null) as with_reversed_at from public.journal_entries where company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' group by 1,2 order by 1,2;

-- integrity
with e as (select j.id,j.entry_date,j.total_debit,j.total_credit,count(l.id) as lines,coalesce(sum(l.debit_amount),0) as debit,coalesce(sum(l.credit_amount),0) as credit,count(l.id) filter(where a.id is null or a.company_id <> j.company_id) as account_mismatch,count(l.id) filter(where a.is_header is distinct from false or a.account_level<3) as invalid_posting_level,count(l.id) filter(where coalesce(l.debit_amount,0)<0 or coalesce(l.credit_amount,0)<0 or (l.debit_amount>0 and l.credit_amount>0)) as invalid_amounts from public.journal_entries j left join public.journal_entry_lines l on l.journal_entry_id=j.id left join public.chart_of_accounts a on a.id=l.account_id where j.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and j.status='posted' and j.entry_date<=date '2026-08-31' group by j.id) select case when entry_date<=date '2025-12-31' then 'through_2025' else 'jan_aug_2026' end as period,count(*) as entries,sum(lines) as lines,count(*) filter(where lines<2) as less_than_two_lines,count(*) filter(where abs(debit-credit)>.005) as unbalanced,count(*) filter(where abs(debit-total_debit)>.005 or abs(credit-total_credit)>.005) as header_mismatch,sum(account_mismatch) as account_company_mismatch,sum(invalid_posting_level) as invalid_posting_level,sum(invalid_amounts) as invalid_amounts,sum(debit-credit) as net from e group by 1 order by 1;

-- references
select case when entry_date<=date '2025-12-31' then 'through_2025' else 'jan_aug_2026' end as period,reference_type,status,count(*) as entries,sum(total_debit) as debit from public.journal_entries where company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and entry_date<=date '2026-08-31' group by 1,2,3 order by 1,2,3;

-- extra_schema
select table_name,column_name,data_type from information_schema.columns where table_schema='public' and table_name in ('accounting_periods','depreciation_records','vehicle_depreciation','vehicles','balance_sheets') order by table_name,ordinal_position;

-- closing
select j.entry_number,j.entry_date,j.reference_type,j.status,j.total_debit,a.account_code,a.account_name,a.account_type,a.account_level,a.is_header,l.debit_amount,l.credit_amount from public.journal_entries j join public.journal_entry_lines l on l.journal_entry_id=j.id join public.chart_of_accounts a on a.id=l.account_id and a.company_id=j.company_id where j.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and j.entry_date<=date '2026-08-31' and (j.reference_type in ('closing','opening') or j.description ~* '(opening|closing|افتتاح|إقفال|اقفال)') order by j.entry_date,j.id,l.line_number;

-- invalid_accounts
select a.account_code,a.account_name,a.account_name_ar,a.account_type,a.is_header,a.account_level,a.is_active,count(*) as lines,sum(l.debit_amount) as debit,sum(l.credit_amount) as credit,sum(l.debit_amount-l.credit_amount) as debit_net from public.journal_entries j join public.journal_entry_lines l on l.journal_entry_id=j.id join public.chart_of_accounts a on a.id=l.account_id and a.company_id=j.company_id where j.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and j.entry_date<=date '2026-08-31' and j.status='posted' and (a.is_header is distinct from false or a.account_level<3) group by a.id order by a.account_code;

-- source_evidence
select 'fixed_assets' as source,count(*) as records,count(*) filter(where purchase_date<=date '2025-12-31') as dated_through_2025,count(*) filter(where purchase_date<=date '2026-08-31') as dated_through_aug2026,count(*) filter(where purchase_date is null) as missing_date,coalesce(sum(purchase_cost),0) as current_recorded_purchase_cost,coalesce(sum(accumulated_depreciation),0) as current_recorded_accum_depreciation from public.fixed_assets where company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' union all select 'vehicles',count(*),count(*) filter(where purchase_date<=date '2025-12-31'),count(*) filter(where purchase_date<=date '2026-08-31'),count(*) filter(where purchase_date is null),coalesce(sum(purchase_cost),0),coalesce(sum(accumulated_depreciation),0) from public.vehicles where company_id='24bc0b21-4e2d-4413-9842-31719a3669f4';

-- dep_periods
select 'depreciation_records' as source,d.depreciation_date::text as date,d.period_type as status,count(*) as records,sum(d.depreciation_amount) as amount,count(*) filter(where d.journal_entry_id is not null) as journal_linked from public.depreciation_records d join public.fixed_assets a on a.id=d.fixed_asset_id where a.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and d.depreciation_date<=date '2026-08-31' group by d.depreciation_date,d.period_type union all select 'accounting_periods',p.start_date::text || ' to ' || p.end_date::text,p.status,count(*),null,null from public.accounting_periods p where p.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and p.start_date<=date '2026-08-31' group by p.start_date,p.end_date,p.status order by source,date;

-- per_cutoff
with dates(as_of) as (values(date '2025-12-31'),(date '2026-08-31')), e as(select d.as_of,j.id,j.status,j.total_debit,j.total_credit,count(l.id) as lines,coalesce(sum(l.debit_amount),0) as debit,coalesce(sum(l.credit_amount),0) as credit,count(l.id) filter(where a.is_header=true) as header_lines,count(l.id) filter(where a.account_level<3) as low_level_lines,count(l.id) filter(where a.is_header is null or a.account_level is null) as undefined_posting_attributes from dates d join public.journal_entries j on j.entry_date<=d.as_of and j.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' left join public.journal_entry_lines l on l.journal_entry_id=j.id left join public.chart_of_accounts a on a.id=l.account_id and a.company_id=j.company_id group by d.as_of,j.id) select as_of,status,count(*) as entries,sum(lines) as lines,sum(debit) as line_debit,sum(credit) as line_credit,count(*) filter(where lines<2) as entries_lt_two_lines,count(*) filter(where abs(debit-credit)>.005) as unbalanced_entries,count(*) filter(where abs(debit-total_debit)>.005 or abs(credit-total_credit)>.005) as header_mismatch,sum(header_lines) as postings_to_headers,sum(low_level_lines) as postings_below_level_three,sum(undefined_posting_attributes) as undefined_posting_attributes from e group by as_of,status order by as_of,status;

-- capital_asset_expense
with dates(as_of) as(values(date '2025-12-31'),(date '2026-08-31')), balances as(select d.as_of,a.id,count(l.id) as lines,coalesce(sum(l.debit_amount),0) as debit,coalesce(sum(l.credit_amount),0) as credit from dates d join public.journal_entries j on j.entry_date<=d.as_of and j.status='posted' and j.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' join public.journal_entry_lines l on l.journal_entry_id=j.id join public.chart_of_accounts a on a.id=l.account_id and a.company_id=j.company_id group by d.as_of,a.id) select d.as_of,a.account_code,a.account_name,a.account_name_ar,a.account_type,a.account_subtype,coalesce(b.lines,0) as posted_lines,coalesce(b.debit,0) as debit,coalesce(b.credit,0) as credit from dates d cross join public.chart_of_accounts a left join balances b on b.as_of=d.as_of and b.id=a.id where a.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' and ((a.account_type='equity') or a.account_type='expenses' or lower(coalesce(a.account_subtype,'')) like '%fixed%' or concat_ws(' ',a.account_name,a.account_name_ar) ~* '(capital|deprecia|fixed assets|رأس المال|راس المال|إهلاك|اهلاك|أصول ثابتة|اصول ثابتة)') order by d.as_of,a.account_code;

-- reversal_cutoff
with dates(as_of) as(values(date '2025-12-31'),(date '2026-08-31')) select d.as_of,count(*) as original_posted_with_reversal_link,count(*) filter(where r.id is null) as missing_reversal,count(*) filter(where r.status<>'posted') as reversal_not_posted,count(*) filter(where r.status='posted' and r.entry_date>d.as_of) as reversal_after_cutoff,coalesce(sum(j.total_debit) filter(where r.status='posted' and r.entry_date>d.as_of),0) as originals_with_later_reversal_gross_debit,count(*) filter(where r.company_id<>j.company_id) as foreign_company_reversal from dates d join public.journal_entries j on j.entry_date<=d.as_of and j.status='posted' and j.company_id='24bc0b21-4e2d-4413-9842-31719a3669f4' left join public.journal_entries r on r.id=j.reversal_entry_id where j.reversal_entry_id is not null group by d.as_of order by d.as_of;

-- vehicle_completeness
select count(*) as vehicle_records,count(*) filter(where purchase_date is null) as missing_purchase_date,count(*) filter(where purchase_cost is null) as missing_purchase_cost,count(*) filter(where purchase_cost=0) as zero_purchase_cost,count(*) filter(where fixed_asset_id is not null) as linked_fixed_asset,sum(purchase_cost) as total_recorded_purchase_cost from public.vehicles where company_id='24bc0b21-4e2d-4413-9842-31719a3669f4';
